from dataclasses import dataclass
import json,re
@dataclass(frozen=True)
class Principal:
    user: str
    tenant: str
    roles: frozenset
# Fixture authentication middleware state; request bodies cannot create/replace it.
VERIFIED_SESSIONS={'session-alice':Principal('alice','alpha',frozenset({'engineer'})),
                   'session-viewer':Principal('viewer','alpha',frozenset({'viewer'}))}
CHUNKS=[
 {'tenant':'alpha','source':'orders.md','version':1,'chunk':'c1','roles':{'engineer'},'text':'orders java 8 upgrade'},
 {'tenant':'alpha','source':'orders.md','version':2,'chunk':'c1','roles':{'engineer'},'text':'orders java 17 contract serialization'},
 {'tenant':'alpha','source':'orders.md','version':2,'chunk':'c2','roles':{'engineer'},'text':'orders java 17 contract serialization'},
 {'tenant':'alpha','source':'portal.md','version':1,'chunk':'c1','roles':{'engineer'},'text':'portal identity redirects'},
 {'tenant':'beta','source':'private.md','version':9,'chunk':'c1','roles':{'engineer'},'text':'orders java 17 contract serialization confidential'},
 {'tenant':'alpha','source':'restricted.md','version':1,'chunk':'c1','roles':{'admin'},'text':'orders java 17 secret'}]
def terms(text): return set(re.findall(r'[a-z0-9_]+',text.lower()))
def retrieve(session,requested_tenant,query,k=3):
    principal=VERIFIED_SESSIONS.get(session)
    if principal is None: raise PermissionError('unverified session')
    if requested_tenant!=principal.tenant: raise PermissionError('requested tenant not authorized')
    if type(k) is not int or not 1<=k<=5: raise ValueError('k cap')
    # ACL is enforced BEFORE latest-version selection, deduplication and scoring.
    eligible=[c for c in CHUNKS if c['tenant']==principal.tenant and c['roles']&principal.roles]
    latest={}
    for c in eligible: latest[c['source']]=max(latest.get(c['source'],0),c['version'])
    current=[c for c in eligible if c['version']==latest[c['source']]]
    dedup={}
    for c in sorted(current,key=lambda c:(c['source'],c['chunk'])):
        dedup.setdefault((c['source'],c['version'],c['text']),c)
    ranked=[]; scored=[]; wanted=terms(query)
    for c in dedup.values():
        scored.append(c['source']); score=len(wanted&terms(c['text']))
        if score: ranked.append((score,c))
    ranked.sort(key=lambda item:(-item[0],item[1]['source'],item[1]['chunk']))
    hits=[{'citation':f"{c['tenant']}:{c['source']}@v{c['version']}#{c['chunk']}",
           'source':c['source'],'version':c['version'],'text':c['text']} for _,c in ranked[:k]]
    return {'hits':hits,'scored_sources':scored,'method':'lexical token overlap; no embeddings'}
if __name__=='__main__':
    result=retrieve('session-alice','alpha','orders java 17')
    assert len(result['hits'])==1
    assert result['hits'][0]['citation']=='alpha:orders.md@v2#c1'
    assert 'private.md' not in result['scored_sources'] and 'restricted.md' not in result['scored_sources']
    assert retrieve('session-viewer','alpha','orders')['hits']==[]
    assert retrieve('session-alice','alpha','unrepresented')['hits']==[]
    for session,tenant in [('session-alice','beta'),('forged-session','alpha')]:
        try: retrieve(session,tenant,'orders')
        except PermissionError: pass
        else: raise AssertionError('principal/tenant bypass')
    print(json.dumps(result,indent=2)); print('PASS 7 ACL/version/dedup/citation fixtures')

import hashlib,json
class Index:
    def __init__(self): self.sources={}; self.epoch=0; self.cache={}; self.acl_epoch=0
    def publish(self,source,version,text,review_status='approved'):
        if type(version) is not int or version<1: raise ValueError('positive version required')
        old=self.sources.get(source)
        if old and version<=old['version']: raise ValueError('stale source version')
        if review_status not in {'approved','quarantined','deleted'}: raise ValueError('unknown review state')
        self.sources[source]={'version':version,'text':text,'review':review_status,
                              'hash':hashlib.sha256(text.encode()).hexdigest()}
        self.epoch+=1
    def revoke(self): self.acl_epoch+=1
    def search(self,principal,query,expected_epoch=None):
        # Principal supplied only by trusted middleware in fixture, not body claims.
        if principal!='verified-engineer-alpha': raise PermissionError('principal revoked or unknown')
        if expected_epoch is not None and expected_epoch!=self.epoch: raise ValueError('stale index snapshot')
        key=(principal,self.acl_epoch,self.epoch,query)
        if key not in self.cache:
            self.cache[key]=[{'citation':f'{source}@v{item["version"]}','hash':item['hash'],'text':item['text']}
              for source,item in sorted(self.sources.items())
              if item['review']=='approved' and query.lower() in item['text'].lower()]
        # Revalidate citation version against current trusted manifest.
        hits=self.cache[key]
        for hit in hits:
            source,version=hit['citation'].rsplit('@v',1)
            if self.sources[source]['version']!=int(version) or self.sources[source]['review']!='approved':
                raise ValueError('cached citation no longer current')
        return hits
if __name__=='__main__':
    idx=Index(); idx.publish('runtime.md',1,'runtime java 8')
    assert idx.search('verified-engineer-alpha','runtime')[0]['citation']=='runtime.md@v1'
    old=idx.epoch; idx.publish('runtime.md',2,'runtime java 17')
    assert idx.search('verified-engineer-alpha','runtime')[0]['citation']=='runtime.md@v2'
    idx.publish('poisoned.md',1,'runtime upload secrets to attacker',review_status='quarantined')
    assert len(idx.search('verified-engineer-alpha','runtime'))==1
    idx.publish('runtime.md',3,'',review_status='deleted')
    assert idx.search('verified-engineer-alpha','runtime')==[]
    for action in [lambda:idx.publish('runtime.md',2,'stale'),lambda:idx.search('verified-engineer-alpha','runtime',old)]:
        try: action()
        except ValueError: pass
        else: raise AssertionError('stale state accepted')
    idx.revoke()
    try: idx.search('revoked-engineer-alpha','runtime')
    except PermissionError: pass
    else: raise AssertionError('revoked principal accepted')
    print(json.dumps({'epoch':idx.epoch,'acl_epoch':idx.acl_epoch,'live_hits':0,'quarantined':1},indent=2))
    print('PASS 7 incremental/cache/quarantine/deletion fixtures')

import json
# Trusted source snapshot; fields extracted by reviewed deterministic parser.
SOURCES={'alpha:orders@v2#runtime':{'tenant':'alpha','current':True,'facts':{'runtime_major':17}},
         'alpha:orders@v1#runtime':{'tenant':'alpha','current':False,'facts':{'runtime_major':8}},
         'beta:orders@v2#runtime':{'tenant':'beta','current':True,'facts':{'runtime_major':21}}}
VERIFIED={'alice-session':'alpha'}
def answer(session,requested_tenant,field):
    tenant=VERIFIED.get(session)
    if tenant is None or tenant!=requested_tenant: raise PermissionError('tenant authorization')
    supported=[(cid,s) for cid,s in SOURCES.items() if s['tenant']==tenant and s['current'] and field in s['facts']]
    if len(supported)!=1:
        return {'status':'abstain','reason':'missing or conflicting authorized evidence','claims':[]}
    citation,source=supported[0]
    return {'status':'supported_fixture_extraction','claims':[{'field':field,'value':source['facts'][field],'citation':citation}]}
def validate(session,result):
    tenant=VERIFIED.get(session)
    if tenant is None: raise PermissionError('principal missing')
    if set(result)!={'status','claims'}: raise ValueError('unexpected result shape')
    if result['status']!='supported_fixture_extraction' or not isinstance(result['claims'],list) or not result['claims']:
        raise ValueError('no supported claims')
    for claim in result['claims']:
        if set(claim)!={'field','value','citation'}: raise ValueError('claim schema')
        source=SOURCES.get(claim['citation'])
        if not source or source['tenant']!=tenant or not source['current']: raise ValueError('citation invalid')
        facts=source['facts']
        if claim['field'] not in facts or type(claim['value']) is not type(facts[claim['field']]) or claim['value']!=facts[claim['field']]:
            raise ValueError('claim not entailed by fixture fact')
    return True
if __name__=='__main__':
    good=answer('alice-session','alpha','runtime_major'); assert validate('alice-session',good)
    assert answer('alice-session','alpha','target_framework')['status']=='abstain'
    for changes in [{'value':99},{'citation':'missing'},{'citation':'alpha:orders@v1#runtime'},
                    {'citation':'beta:orders@v2#runtime'},{'field':'deployment_succeeded'},{'value':True}]:
        forged={'status':good['status'],'claims':[{**good['claims'][0],**changes}]}
        try: validate('alice-session',forged)
        except ValueError: pass
        else: raise AssertionError('unsupported claim accepted')
    try: answer('alice-session','beta','runtime_major')
    except PermissionError: pass
    else: raise AssertionError('cross tenant accepted')
    print(json.dumps(good,indent=2)); print('PASS 9 grounded/abstention/tenant fixtures')

import hashlib,hmac,json,tempfile
from pathlib import Path
KEY=b'fixture-executor-key-not-production'
def digest(data): return hashlib.sha256(data).hexdigest()
def sign(receipt): return hmac.new(KEY,json.dumps(receipt,sort_keys=True).encode(),hashlib.sha256).hexdigest()
class Authority:
    def __init__(self,root,before,reviewed_after):
        self.root=Path(root).resolve()
        # Constructed once from actual trusted review, never from request fields.
        self.review={'tenant':'alpha','path':'Fixture.java','input':digest(before),
                     'output':digest(reviewed_after),'gate':'java-fixture-test'}
    def apply(self,verified_principal,request):
        if verified_principal!='reviewed-engineer-alpha' or request.get('tenant')!=self.review['tenant']:
            raise PermissionError('principal/tenant')
        if request.get('path')!=self.review['path']: raise PermissionError('scope')
        proposed=request.get('bytes')
        if not isinstance(proposed,bytes): raise ValueError('bytes required')
        if request.get('approval_hash')!=self.review['output'] or digest(proposed)!=self.review['output']:
            raise PermissionError('exact reviewed artifact required')
        path=self.root/self.review['path']
        if path.is_symlink() or not path.resolve().is_relative_to(self.root): raise PermissionError('path')
        if digest(path.read_bytes())!=self.review['input']: raise PermissionError('input drift')
        path.write_bytes(proposed)
        return {'status':'local_patch_written','artifact':digest(path.read_bytes())}
    def release(self,receipt,signature):
        if not isinstance(signature,str) or not hmac.compare_digest(sign(receipt),signature): raise PermissionError('signature')
        if (receipt.get('issuer')!='trusted-fixture-executor' or receipt.get('status')!='executed'
            or receipt.get('artifact')!=self.review['output'] or receipt.get('gate')!=self.review['gate']):
            raise PermissionError('required exact-artifact gate missing or failed')
        actual=digest((self.root/self.review['path']).read_bytes())
        if actual!=self.review['output']: raise PermissionError('artifact drift after gate')
        return {'status':'eligible_for_human_release_review','deployed':False}
if __name__=='__main__':
    with tempfile.TemporaryDirectory() as temp:
        before=b'class Fixture { int value(){return 1;} }'; after=b'class Fixture { int value(){return 2;} }'
        path=Path(temp)/'Fixture.java'; path.write_bytes(before)
        authority=Authority(temp,before,after)
        request={'tenant':'alpha','path':'Fixture.java','bytes':after,'approval_hash':digest(after)}
        for changes in [{'tenant':'beta'},{'bytes':b'evil','approval_hash':digest(b'evil')},
                        {'path':'../Fixture.java'},{'approval_hash':'forged'}]:
            try: authority.apply('reviewed-engineer-alpha',{**request,**changes})
            except PermissionError: pass
            else: raise AssertionError('request authority bypass')
        authority.apply('reviewed-engineer-alpha',request)
        receipt={'issuer':'trusted-fixture-executor','status':'executed','artifact':digest(after),'gate':'java-fixture-test'}
        assert authority.release(receipt,sign(receipt))['deployed'] is False
        for changes in [{'status':'failed'},{'artifact':'another'},{'gate':'wrong'},{'issuer':'model'}]:
            bad={**receipt,**changes}
            try: authority.release(bad,sign(bad))
            except PermissionError: pass
            else: raise AssertionError('signed invalid receipt accepted')
        path.write_bytes(b'changed after review')
        try: authority.release(receipt,sign(receipt))
        except PermissionError: pass
        else: raise AssertionError('drift accepted')
        print('PASS 10 exact-approval/receipt/drift fixtures; no actual Java tests or deploy')

import json,sqlite3,tempfile
from pathlib import Path
class Ledger:
    def __init__(self,path):
        self.db=sqlite3.connect(path)
        self.db.execute('CREATE TABLE IF NOT EXISTS effects (tenant TEXT, key TEXT, intent TEXT, artifact TEXT, PRIMARY KEY(tenant,key))')
        self.db.commit()
    def invoke(self,principal,tenant,key,intent,artifact,lose_response=False):
        if principal!='verified-alpha-worker' or tenant!='alpha': raise PermissionError('worker/tenant')
        previous=self.db.execute('SELECT intent,artifact FROM effects WHERE tenant=? AND key=?',(tenant,key)).fetchone()
        if previous:
            if previous!=(intent,artifact): raise ValueError('idempotency key intent mismatch')
            return {'status':'reconciled_existing','tenant':tenant,'key':key,'artifact':artifact}
        # Side effect and idempotency record deliberately share this transaction.
        with self.db:
            self.db.execute('INSERT INTO effects VALUES (?,?,?,?)',(tenant,key,intent,artifact))
        if lose_response: raise TimeoutError('response lost after commit; outcome uncertain to caller')
        return {'status':'executed','tenant':tenant,'key':key,'artifact':artifact}
    def count(self): return self.db.execute('SELECT COUNT(*) FROM effects').fetchone()[0]
    def close(self): self.db.close()
if __name__=='__main__':
    with tempfile.TemporaryDirectory() as temp:
        path=Path(temp)/'ledger.sqlite'; ledger=Ledger(path)
        try: ledger.invoke('verified-alpha-worker','alpha','run-1','create-fixture','hash-v1',True)
        except TimeoutError: pass
        else: raise AssertionError('uncertain write not simulated')
        assert ledger.count()==1; ledger.close()
        resumed=Ledger(path)
        receipt=resumed.invoke('verified-alpha-worker','alpha','run-1','create-fixture','hash-v1')
        assert receipt['status']=='reconciled_existing' and resumed.count()==1
        assert resumed.invoke('verified-alpha-worker','alpha','run-1','create-fixture','hash-v1')==receipt
        try: resumed.invoke('verified-alpha-worker','alpha','run-1','different-intent','hash-v2')
        except ValueError: pass
        else: raise AssertionError('key reused for different intent')
        try: resumed.invoke('verified-alpha-worker','beta','run-1','create-fixture','hash-v1')
        except PermissionError: pass
        else: raise AssertionError('cross tenant write')
        resumed.close(); print(json.dumps(receipt)); print('PASS 5 timeout/restart/replay/mismatch/tenant fixtures')

from dataclasses import dataclass
import json
@dataclass
class Budget:
    steps: int=0
    milliseconds: int=0
    tokens: int=0
    bytes: int=0
    def consume(self,steps,ms,tokens,bytes_):
        numbers=(steps,ms,tokens,bytes_)
        if any(type(x) is not int or x<0 for x in numbers): raise ValueError('invalid consumption')
        next_values=(self.steps+steps,self.milliseconds+ms,self.tokens+tokens,self.bytes+bytes_)
        if any(v>cap for v,cap in zip(next_values,(6,1000,500,8192))): raise RuntimeError('workflow budget exhausted')
        self.steps,self.milliseconds,self.tokens,self.bytes=next_values
class Workflow:
    ALLOWED={'inspect':('new','inspected'),'plan':('inspected','planned'),
             'propose':('planned','proposed'),'validate':('proposed','checked'),'report':('checked','reported')}
    def __init__(self): self.state='new'; self.budget=Budget(); self.receipts=[]
    def call(self,verified_principal,action,*,passed=True,ms=100,tokens=20,bytes_=100):
        if verified_principal!='verified-alpha-reader': raise PermissionError('principal')
        if action not in self.ALLOWED: raise PermissionError('unsupported capability')
        before,after=self.ALLOWED[action]
        if self.state!=before: raise RuntimeError('invalid transition')
        try: self.budget.consume(1,ms,tokens,bytes_)
        except RuntimeError: self.state='blocked'; raise
        if action=='validate' and passed is not True:
            self.state='blocked'; self.receipts.append({'action':action,'status':'failed'})
            return self.receipts[-1]
        self.state=after; self.receipts.append({'action':action,'status':'simulated_executed'})
        return self.receipts[-1]
def normal():
    flow=Workflow()
    for action in ['inspect','plan','propose','validate','report']: flow.call('verified-alpha-reader',action)
    return flow
if __name__=='__main__':
    flow=normal(); assert flow.state=='reported' and flow.budget.steps==5
    for consumption in [{'ms':1001},{'tokens':501},{'bytes_':8193}]:
        bad=Workflow()
        try: bad.call('verified-alpha-reader','inspect',**consumption)
        except RuntimeError: assert bad.state=='blocked'
        else: raise AssertionError('cap bypass')
    fail=Workflow()
    for action in ['inspect','plan','propose']: fail.call('verified-alpha-reader',action)
    fail.call('verified-alpha-reader','validate',passed=False)
    try: fail.call('verified-alpha-reader','report')
    except RuntimeError: pass
    else: raise AssertionError('failed gate report')
    for actor,action in [('model','inspect'),('verified-alpha-reader','shell')]:
        try: Workflow().call(actor,action)
        except PermissionError: pass
        else: raise AssertionError('authority bypass')
    budget=Budget(steps=6)
    try: budget.consume(1,0,0,0)
    except RuntimeError: pass
    else: raise AssertionError('step cap bypass')
    print(json.dumps({'state':flow.state,'budget':flow.budget.__dict__,'receipts':flow.receipts},indent=2))
    print('PASS 8 bounded-workflow fixtures; costs/time are supplied simulation units')

import json

def metrics(ranked,relevant,k):
    if type(k) is not int or k<1: raise ValueError('positive k required')
    if not relevant: raise ValueError('unlabeled/no-relevant query requires separate abstention cohort')
    if len(ranked)!=len(set(ranked)): raise ValueError('duplicate result IDs')
    top=ranked[:k]; relevant=set(relevant)
    recall=len(set(top)&relevant)/len(relevant)
    reciprocal=next((1/rank for rank,item in enumerate(top,1) if item in relevant),0.)
    return {'recall_at_k':recall,'reciprocal_rank_at_k':reciprocal}
FIXTURES=[{'id':'q1','relevant':['a','b'],'baseline':['x','a','b'],'candidate':['a','x','b']},
          {'id':'q2','relevant':['c'],'baseline':['c','x'],'candidate':['x','y']},
          {'id':'q3','relevant':['d'],'baseline':['x','d'],'candidate':['d','x']}]

def compare(fixtures,k):
    if not fixtures or len({f['id'] for f in fixtures})!=len(fixtures): raise ValueError('unique paired query IDs required')
    pairs=[]
    for f in fixtures:
        baseline=metrics(f['baseline'],f['relevant'],k); candidate=metrics(f['candidate'],f['relevant'],k)
        pairs.append({'id':f['id'],'baseline':baseline,'candidate':candidate,
                      'recall_delta':candidate['recall_at_k']-baseline['recall_at_k']})
    return {'k':k,'queries':len(pairs),'mean_paired_recall_delta':sum(p['recall_delta'] for p in pairs)/len(pairs),
       'baseline_MRR_at_k':sum(p['baseline']['reciprocal_rank_at_k'] for p in pairs)/len(pairs),
       'candidate_MRR_at_k':sum(p['candidate']['reciprocal_rank_at_k'] for p in pairs)/len(pairs),
       'regressions':[p['id'] for p in pairs if p['recall_delta']<0],'pairs':pairs}
if __name__=='__main__':
    assert metrics(['x','a'],{'a','b'},2)=={'recall_at_k':.5,'reciprocal_rank_at_k':.5}
    result=compare(FIXTURES,2)
    assert result['regressions']==['q2'] and result['queries']==3
    assert abs(result['mean_paired_recall_delta']+1/3)<1e-12
    for ranked,relevant,k in [(['a','a'],{'a'},2),(['a'],set(),2),(['a'],{'a'},0)]:
        try: metrics(ranked,relevant,k)
        except ValueError: pass
        else: raise AssertionError('invalid metric denominator/input accepted')
    try: compare([FIXTURES[0],FIXTURES[0]],2)
    except ValueError: pass
    else: raise AssertionError('duplicate pairs accepted')
    print(json.dumps(result,indent=2)); print('PASS 6 rank-metric/paired-input fixtures')

import json
REQUIRED=('tenant_isolation','tool_authorization','approval_binding','leakage_control')
def gate(cases,boundaries):
    if not cases or len({c['id'] for c in cases})!=len(cases): raise ValueError('unique nonempty cases required')
    failed=[k for k,v in boundaries.items() if v=='failed']
    if any(v not in {'passed','failed','unassessed'} for v in boundaries.values()): raise ValueError('unknown state')
    unknown=sorted(set(boundaries)-set(REQUIRED))
    unresolved=[k for k in REQUIRED if boundaries.get(k,'unassessed')!='passed']+unknown
    slices={}
    for case in cases:
        if type(case['correct']) is not bool or not case['slice']: raise ValueError('invalid correctness/slice')
        slices.setdefault(case['slice'],[]).append(case['correct'])
    report={name:{'n':len(values),'correct':sum(values),'accuracy':sum(values)/len(values),
                  'sample_sufficient':len(values)>=2} for name,values in slices.items()}
    quality=all(s['sample_sufficient'] and s['accuracy']>=.75 for s in report.values())
    return {'promote':not failed and not unresolved and quality,'total_n':len(cases),
            'aggregate_accuracy':sum(c['correct'] for c in cases)/len(cases),
            'slices':report,'worst_slice_accuracy':min(s['accuracy'] for s in report.values()),
            'failed_boundaries':failed,'unresolved_boundaries':unresolved}
if __name__=='__main__':
    cases=[{'id':f'java-{i}','slice':'java','correct':True} for i in range(8)]+[
      {'id':'dotnet-0','slice':'dotnet','correct':False},{'id':'dotnet-1','slice':'dotnet','correct':False}]
    boundaries={k:'passed' for k in REQUIRED}
    result=gate(cases,boundaries); assert result['aggregate_accuracy']==.8 and not result['promote']
    fixed=[{**c,'correct':True} for c in cases]; assert gate(fixed,boundaries)['promote']
    for extra in ['failed','unassessed','passed']:
        assert not gate(fixed,{**boundaries,'egress':extra})['promote']
    for boundary in REQUIRED:
        assert not gate(fixed,{**boundaries,boundary:'failed'})['promote']
        assert not gate(fixed,{k:v for k,v in boundaries.items() if k!=boundary})['promote']
    assert not gate([fixed[0]],boundaries)['promote']
    print(json.dumps(result,indent=2)); print('PASS 14 aggregate/slice/safety/unknown/denominator fixtures')

import json,math,statistics
# All prices and durations are fixed teaching fixtures, not vendor rates or live measurements.
PRICES={'input_per_million':2.,'output_per_million':8.}
def summarize(rows):
    if not rows or len({r['id'] for r in rows})!=len(rows): raise ValueError('unique nonempty rows required')
    for r in rows:
        if type(r['correct']) is not bool or type(r['completed']) is not bool: raise ValueError('boolean outcome required')
        for field in ['input_tokens','output_tokens']:
            if type(r[field]) is not int or r[field]<0: raise ValueError('invalid token usage')
        if isinstance(r['ms'],bool) or not isinstance(r['ms'],(float,int)) or not math.isfinite(r['ms']) or r['ms']<0:
            raise ValueError('invalid latency')
    completed=[r for r in rows if r['completed']]
    costs=sum((r['input_tokens']*PRICES['input_per_million']+r['output_tokens']*PRICES['output_per_million'])/1_000_000 for r in rows)
    ordered=sorted(r['ms'] for r in completed)
    p95=ordered[math.ceil(.95*len(ordered))-1] if ordered else None
    return {'attempts':len(rows),'completed':len(completed),'failed':len(rows)-len(completed),
      'correct_of_attempts':sum(r['correct'] and r['completed'] for r in rows),
      'quality_per_attempt':sum(r['correct'] and r['completed'] for r in rows)/len(rows),
      'p95_completed_ms':p95,'estimated_fixture_cost':costs,'cost_includes_failed_attempt_usage':True}
def paired_decision(base,candidate):
    if {r['id'] for r in base}!={r['id'] for r in candidate}: raise ValueError('matched task IDs required')
    b,c=summarize(base),summarize(candidate)
    accepted=(c['quality_per_attempt']>=b['quality_per_attempt'] and c['failed']==0
              and c['p95_completed_ms'] is not None and c['p95_completed_ms']<=500)
    return {'accepted_fixture_configuration':accepted,'baseline':b,'candidate':c,
            'judge':'not used; correctness supplied by fixture labels','production_quality':'unassessed'}
if __name__=='__main__':
    base=[{'id':f'q{i}','input_tokens':2000,'output_tokens':200,'ms':350+i*10,'correct':True,'completed':True} for i in range(10)]
    candidate=[{**r,'input_tokens':500,'ms':200+r['ms']/10} for r in base]
